// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller, uint64 newNumber) public {
        uint64 _number = newNumber;
        uint64 _timestamp = uint64(block.timestamp);
        uint256 _basefee = tx.gasprice;
        bytes32 _hash = bytes32(uint256(uint160(caller)));
        uint64 _sequenceNumber = 1;
        bytes32 _batcherHash = bytes32(0);
        uint256 _l1FeeOverhead = 0;
        uint256 _l1FeeScalar = 1;

        bool ok;
        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        address depositor = c.DEPOSITOR_ACCOUNT();

        assertTrue(ok == (caller == depositor));
    }
}
